#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Initialize A row by row to improve spatial locality and
     reduce index arithmetic. Semantics are identical to the
     original nested loops. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE* Ai = A[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + (DATA_TYPE)1;

      for (j = i+1; j < n; j++)
	Ai[j] = (DATA_TYPE)0;

      /* Overwrite the diagonal with 1, as in the original code. */
      Ai[i] = (DATA_TYPE)1;
    }

  /* Make the matrix positive semi-definite. */
  /* not necessary for LU, but using same code as cholesky */
  int r,s,t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Create local restrict-qualified views to help the compiler
     with alias analysis. The underlying storage and indexing
     remain unchanged. */
  DATA_TYPE (* restrict a)[n] = A;
  DATA_TYPE (* restrict b)[n] = POLYBENCH_ARRAY(B);

  /* Zero B row by row using memset for better performance and
     cache behavior than element-wise initialization. */
  for (r = 0; r < n; ++r)
    memset(b[r], 0, (size_t)n * sizeof(DATA_TYPE));

  /* Compute B = A * A^T (Gram matrix).
     New loop order: r, s, t. For each (r,s) pair we perform a
     sequential reduction over t in the order t = 0..n-1,
     exactly matching the order of contributions in the original
     code. This preserves floating-point evaluation order for
     each B[r][s] while greatly improving data locality:
       - Ar[t] and As[t] are read contiguously along rows.
       - Br[s] is kept in a register during the reduction. */
#if defined(_OPENMP)
#pragma omp parallel for schedule(static) private(s,t)
#endif
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE * restrict Br = b[r];
      const DATA_TYPE * restrict Ar = a[r];

      for (s = 0; s < n; ++s)
	{
	  const DATA_TYPE * restrict As = a[s];
	  DATA_TYPE sum = (DATA_TYPE)0;

	  for (t = 0; t < n; ++t)
	    sum += Ar[t] * As[t];

	  Br[s] = sum;
	}
    }

  /* Copy B back into A. Using memcpy on each row is more efficient
     than element-wise copying and preserves all values exactly. */
  for (r = 0; r < n; ++r)
    memcpy(a[r], b[r], (size_t)n * sizeof(DATA_TYPE));

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_lu [[gnu::flatten, gnu::noinline]] (int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local restrict-qualified view of A for better alias analysis.
     The layout is still exactly the same n-by-n VLA. */
  DATA_TYPE (* restrict a)[n] = A;
  const int pb_n = _PB_N;

#pragma scop
  for (i = 0; i < pb_n; i++) {
    /* Cache the current row pointer to reduce index computations. */
    DATA_TYPE * restrict Ai = a[i];

    /* First, compute L(i, j) for j < i.

       Original code:
         for (j = 0; j < i; j++) {
            for (k = 0; k < j; k++)
               A[i][j] -= A[i][k] * A[k][j];
            A[i][j] /= A[j][j];
         }

       Below we keep the same k-iteration order for the reduction and
       the same final division, but accumulate into a local scalar
       'sum' instead of writing back to A[i][j] at every step. This
       preserves the exact sequence of floating-point operations on
       A[i][j]. */
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];

      for (k = 0; k < j; k++) {
        sum -= Ai[k] * a[k][j];
      }

      sum /= a[j][j];
      Ai[j] = sum;
    }

    /* Then update the U-part of row i for j >= i.

       Original code:
         for (j = i; j < _PB_N; j++) {
           for (k = 0; k < i; k++)
             A[i][j] -= A[i][k] * A[k][j];
         }

       We interchange the j and k loops to make j the innermost loop.
       For each fixed k, we stream along row segments Ai[j] and a[k][j],
       which are contiguous in memory. For a fixed (i,j), the updates
       over k still occur in the same order k = 0..i-1, so the
       floating-point evaluation order for A[i][j] is unchanged. */
    for (k = 0; k < i; k++) {
      const DATA_TYPE aik = Ai[k];
      DATA_TYPE * restrict Ak = a[k];

      for (j = i; j < pb_n; j++) {
        Ai[j] -= aik * Ak[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
