#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Explicit VLA pointer with restrict to give the compiler precise
   * aliasing and dimensionality information for the matrix A.
   */
  DATA_TYPE (*restrict A_)[n] = A;

  /* Initial lower-triangular structure with unit diagonal. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *Ai = A_[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j % n) / n + 1;

      for (j = i+1; j < n; j++)
	Ai[j] = (DATA_TYPE)0;

      Ai[i] = (DATA_TYPE)1;
    }

  /* Make the matrix positive semi-definite.
   * (Not necessary for LU, but using same code as cholesky.)
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Compute B = A * A^T (Gram matrix).
   *
   * Compared to the original version, which:
   *   - first zeroed B
   *   - then accumulated B[r][s] += A[r][t] * A[s][t] with loops t-r-s
   *
   * this version:
   *   - computes each B[r][s] via a local accumulator 'sum'
   *   - traverses the innermost loop over the contiguous dimension 't'
   *     in both rows A_[r] and A_[s], enabling efficient vectorization
   *     and improving cache locality
   *   - performs exactly the same arithmetic for each (r, s) pair
   *     (same products, same order in t), but with far fewer loads
   *     and stores to B.
   */
  for (r = 0; r < n; ++r)
    {
      const DATA_TYPE *restrict Ar = A_[r];

      for (s = 0; s < n; ++s)
        {
          const DATA_TYPE *restrict As = A_[s];
          DATA_TYPE sum = (DATA_TYPE)0;

          /* Dot product of row r and row s. */
          for (t = 0; t < n; ++t)
            sum += Ar[t] * As[t];

          B_[r][s] = sum;
        }
    }

  /* Copy the result back into A, preserving the external behavior of
   * the original code (A is overwritten by the positive semi-definite
   * matrix).
   */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict Arw = A_[r];
      const DATA_TYPE *restrict Br = B_[r];

      for (s = 0; s < n; ++s)
        Arw[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static __attribute__((noinline, flatten))
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Explicit VLA pointer with restrict for better aliasing information. */
  DATA_TYPE (*restrict A_)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

    /* Compute the strictly lower triangular part of row i (L factor).
     *
     * Original code (per j):
     *   for (k = 0; k < j; k++)
     *     A[i][j] -= A[i][k] * A[k][j];
     *   A[i][j] /= A[j][j];
     *
     * We preserve the dependency order in j (0..i-1), but accumulate
     * into a scalar 'sum' to reduce memory traffic and provide a clean
     * inner loop to the optimizer.
     */
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = A_[i][j];

      for (k = 0; k < j; k++) {
        sum -= A_[i][k] * A_[k][j];
      }

      sum /= A_[j][j];
      A_[i][j] = sum;
    }

    /* Update the upper part of row i (U factor, including diagonal).
     *
     * Original code:
     *   for (j = i; j < _PB_N; j++)
     *     for (k = 0; k < i; k++)
     *       A[i][j] -= A[i][k] * A[k][j];
     *
     * Here we interchange the j and k loops:
     *
     *   for (k = 0; k < i; k++) {
     *     aik = A[i][k];
     *     for (j = i; j < _PB_N; j++)
     *       A[i][j] -= aik * A[k][j];
     *   }
     *
     * For each fixed (i, j), the sequence of updates over k is still
     * in increasing k order (0..i-1), so the arithmetic for that
     * element is unchanged.  The innermost loop now traverses
     * contiguous elements in both A_[i] and A_[k], turning the update
     * into a DAXPY-like operation which vectorizes well and improves
     * cache locality.
     */
    for (k = 0; k < i; k++) {
      const DATA_TYPE aik = A_[i][k];
      DATA_TYPE *restrict Ak = A_[k];

      for (j = i; j < _PB_N; j++) {
        A_[i][j] -= aik * Ak[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
