#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Original triangular initialization of A (O(n^2), left as-is). */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite.
     (Not necessary for LU, but using same code as cholesky.) */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Create restrict-qualified, 1D views of A and B to help the compiler
     generate better code (fewer address computations, more vectorization). */
  DATA_TYPE (*restrict Bp)[n] = POLYBENCH_ARRAY(B);
  DATA_TYPE *restrict b = &Bp[0][0];
  DATA_TYPE *restrict a = &A[0][0];
  const int lda = n;
  const int nn  = n * n;

  /* Initialize B to zero using a single contiguous loop for better cache use. */
  for (int idx = 0; idx < nn; ++idx)
    b[idx] = (DATA_TYPE)0;

  /* Compute B = A * A^T
     B[r][s] = sum_t A[r][t] * A[s][t]
     Loop ordering and 1D indexing improve data locality. */
  for (t = 0; t < n; ++t)
    {
      const int tCol = t;  /* column index in A */

      for (r = 0; r < n; ++r)
	{
	  const DATA_TYPE Ar_t = a[r * lda + tCol]; /* A[r][t] */
	  const int rRow = r * lda;

	  /* Inner-most loop is contiguous in memory over s for B[r][s]. */
	  for (s = 0; s < n; ++s)
	    {
	      /* A[s][t] = a[s * lda + tCol] */
	      b[rRow + s] += Ar_t * a[s * lda + tCol];
	    }
	}
    }

  /* Copy the positive semi-definite matrix back into A.
     Again use 1D indexing for simpler address computation. */
  for (r = 0; r < n; ++r)
    {
      const int rRow = r * lda;
      for (s = 0; s < n; ++s)
	a[rRow + s] = b[rRow + s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations:
   - Use a single, restrict-qualified 1D view of A to simplify address
     arithmetic and help vectorization.
   - For the lower-triangular part (L), accumulate into a scalar 'sum'
     so A[i][j] is loaded/stored once per element.
   - For the upper-triangular part (U), reorder loops into a sequence of
     rank-1 updates (outer-product form). For each k, we update the whole
     row segment A[i][i..N) using A[i][k] and row k. For each fixed (i,j),
     the sequence of arithmetic operations over k is identical to the
     original code, so the final value is unchanged.
*/
static
void __attribute__((flatten, noinline))
kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  const int n_bound = _PB_N;

  /* Get a restrict-qualified 1D pointer to the contiguous data.
     From this point on we only access the matrix through 'a' or
     pointers derived from it, which satisfies the 'restrict' contract. */
  DATA_TYPE *restrict a = &A[0][0];
  const int lda = n;

#pragma scop
  for (int i = 0; i < n_bound; i++)
    {
      const int iRow = i * lda;
      DATA_TYPE *restrict Ai = a + iRow; /* Row i */

      /* Compute the strictly lower-triangular entries L(i, 0..i-1). */
      for (int j = 0; j < i; j++)
	{
	  /* Start from the current A[i][j] value. */
	  DATA_TYPE sum = Ai[j];

	  /* Dot product of row i (0..j-1) with column j (0..j-1). */
	  int kRow = 0;
	  for (int k = 0; k < j; k++, kRow += lda)
	    {
	      /* A[i][k] = Ai[k], A[k][j] = a[kRow + j] */
	      sum -= Ai[k] * a[kRow + j];
	    }

	  /* Divide by the diagonal element A[j][j]. */
	  Ai[j] = sum / a[j * lda + j];
	}

      /* Compute the upper-triangular entries U(i, i..N-1).
         Original code:
           for (j = i; j < N; ++j)
             for (k = 0; k < i; ++k)
               A[i][j] -= A[i][k] * A[k][j];

         Here we interchange the j and k loops, which is safe because,
         for each fixed (i,j), the updates over k are independent of
         other columns and occur in the same k order. */
      for (int k = 0, kRow = 0; k < i; k++, kRow += lda)
	{
	  const DATA_TYPE Aik = Ai[k];              /* A[i][k] */
	  const DATA_TYPE *restrict Ak = a + kRow;  /* Row k   */

	  for (int j = i; j < n_bound; j++)
	    {
	      /* A[i][j] -= A[i][k] * A[k][j]; */
	      Ai[j] -= Aik * Ak[j];
	    }
	}
    }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
