     (Not necessary for LU itself, but kept to match the original
      PolyBench initialization and Cholesky benchmark.)
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Local restrict-qualified views to help the compiler with aliasing. */
  DATA_TYPE (*restrict b_)[n] = POLYBENCH_ARRAY(B);
  DATA_TYPE (*restrict a_)[n] = A;

  /* Zero-initialize B: row-major writes for good spatial locality. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE* restrict Br = b_[r];
      for (s = 0; s < n; ++s)
        Br[s] = 0;
    }

  /* Compute B = A * A^T.
     Loop order (t, r, s) is kept identical to the original code so that
     the sequence of floating-point operations for each B[r][s] is
     unchanged; we only hoist common subexpressions (row pointer and
     A[r][t]) out of the innermost loop to improve reuse and reduce
     address arithmetic.
   */
  for (t = 0; t < n; ++t)
    for (r = 0; r < n; ++r)
      {
        DATA_TYPE* restrict Br = b_[r];
        const DATA_TYPE art = a_[r][t]; /* A[r][t], reused across all s. */
        for (s = 0; s < n; ++s)
