      }

  /* Copy B back into A, again using row-major traversal. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE* restrict Ar = a_[r];
      DATA_TYPE* restrict Br = b_[r];
      for (s = 0; s < n; ++s)
        Ar[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


