  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static void __attribute__((noinline,flatten))
kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  (void)n; /* Size is provided via PolyBench macro _PB_N. */

#pragma scop
  for (int i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ai = A[i];

    /* Compute the L part: strictly lower-triangular entries of row i.
       This loop follows the standard (unblocked) Doolittle LU step:

         Ai[j] = (Ai[j] - sum_{k=0..j-1} Ai[k] * A[k][j]) / A[j][j]

       We keep the dependence on previously computed Ai[k] by
       iterating j from 0 to i-1, exactly as in the original code.
       The inner accumulation uses a local 'sum' variable to reduce
       memory traffic while preserving the order of floating-point
       operations.
     */
    for (int j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];
      for (int k = 0; k < j; k++) {
        const DATA_TYPE *restrict Ak = A[k];
        sum -= Ai[k] * Ak[j];  /* A[k][j] */
      }
      Ai[j] = sum / A[j][j];
    }

    /* Compute the U part: entries from column i to the end of row i.
       Original code:

         for (j = i; j < N; j++)
           for (k = 0; k < i; k++)
             A[i][j] -= A[i][k] * A[k][j];

       We rewrite this as a sequence of rank-1 updates:

         for (k = 0; k < i; k++) {
           aik = A[i][k];
           for (j = i; j < N; j++)
             A[i][j] -= aik * A[k][j];
         }

       For each fixed (i,j), the sequence of updates over k is still
       exactly k = 0..i-1, so the floating-point evaluation order for
       A[i][j] is unchanged.  However, this exposes a contiguous inner
       loop over j for each (i,k), allowing much better reuse of
       A[i][k] and A[k][j], and enabling efficient vectorization.
     */
    for (int k = 0; k < i; k++) {
      const DATA_TYPE aik = Ai[k];
      const DATA_TYPE *restrict Ak = A[k];

#pragma GCC ivdep
      for (int j = i; j < _PB_N; j++) {
        Ai[j] -= aik * Ak[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
